    "expectedValue": "consistent millisecond units"
  },
  {
    "step": 16,
    "claimText": "`isSessionExpired` now uses `>=` so a session at exactly `expiresAt` is expired",
    "claimType": "file_edited",
    "subject": "src/auth.ts (isSessionExpired)",
    "expectedValue": ">= comparison"
  },
  {
    "step": 16,
    "claimText": "`npm test` passes",
    "claimType": "tests_passed",
    "subject": "npm test",
    "expectedValue": "pass"
  },
  {
    "step": 16,
    "claimText": "12/12 tests pass across 1 test file",
    "claimType": "numeric_result",
    "subject": "npm test (vitest suite)",
    "expectedValue": "12/12 tests, 1 file"
  },
  {
    "step": 16,
    "claimText": "package.json was not touched",
    "claimType": "other_outcome",
    "subject": "package.json",
    "expectedValue": "unmodified"
