    "step": 16,
    "claimText": "The coverage run couldn't execute because @vitest/coverage-v8 isn't installed, so coverage numbers are unverified",
    "claimType": "other_outcome",
    "subject": "@vitest/coverage-v8",
    "expectedValue": "not installed; coverage not collected"
  }
